using System.Globalization;
using EFT;
using EFT.InventoryLogic;
using SAIN.Preset.Shared.Models.Preset.Personalities;
using UnityEngine;

namespace LiveRaid.Client.Bots
{
    /// <summary>
    /// The packrat ("Барахольщик", F12 -> 6 "Packrat chance, %"). A player's tester asked for a knife-only loot rat: cheap or no weapon, a big
    /// backpack, loots the map fast, runs from danger and fights only when cornered. With a knife it never comes - with a pistol it does: with the
    /// chance from F12, one lone PMC of a raid (never more) is generated by the server with a pistol and one of the biggest bags (LiveRaid.Server
    /// Packrat.cs, archetype "packrat"). Here it is recognised (the server tells its profile id) and played:
    ///  - a looter through and through: greed and curiosity at the top, no quests to speak of, never a hot-drop, a plain SAIN personality
    ///    (the passive ones stand still for minutes);
    ///  - keeps out of fights: an enemy it meets farther than 12 m off it breaks off from (CombatSense), never pushes or presses; gunfire it hears
    ///    it leaves (GunfireResponse), a noise it slips away from (NoiseResponse);
    ///  - cornered - the enemy within 12 m or no way out - it fights like anyone.
    /// </summary>
    public static class Packrat
    {
        private static readonly System.Collections.Generic.HashSet<string> _tagged = new System.Collections.Generic.HashSet<string>();
        private static bool _armed;
        private static string _chosen;
        private static string _assigned;
        private static readonly System.Collections.Generic.List<BotOwner> _toSeparate = new System.Collections.Generic.List<BotOwner>();
        private static float _askedAt = -99f;

        public static string Seen { get; private set; }

        public static string Summary => Seen != null ? $"packrat: {Seen}" : "packrat: none this raid";

        /// <summary>The server rolled a packrat for this raid (chance from F12), and its kit sits on a profile or two in the pool of QuestingBots.</summary>
        public static bool Armed => _armed;

        /// <summary>The profile id given to a lone group as the raid's packrat (Patches/PackratPoolPatch.cs), or null.</summary>
        public static string Assigned => _assigned;

        public static bool Wanted => (Settings.PackratChance?.Value ?? 0) > 0;

        public static bool IsTagged(string profileId) => profileId != null && _tagged.Contains(profileId);

        public static void Assign(string profileId) => _assigned = profileId;

        /// <summary>Asks the server which profiles carry the packrat's kit (at most every 2 s unless forced).</summary>
        public static void Refresh(bool force = false)
        {
            if (!Wanted)
            {
                return;
            }

            float now = Time.realtimeSinceStartup;
            if (!force && now - _askedAt < 2f)
            {
                return;
            }

            _askedAt = now;
            try
            {
                string json = SPT.Common.Http.RequestHandler.GetJson("/liveraid/packrat/who");
                _armed = Field(json, "armed") == "1";
                _tagged.Clear();
                foreach (string id in (Field(json, "ids") ?? "").Split(','))
                {
                    if (id.Length > 0)
                    {
                        _tagged.Add(id);
                    }
                }
            }
            catch (System.Exception)
            {
                // the server part is off or not reached - no packrat then
            }
        }

        public static void Clear()
        {
            _tagged.Clear();
            _armed = false;
            _assigned = null;
            _chosen = null;
            _toSeparate.Clear();
            _askedAt = -99f;
            Seen = null;
            Patches.PackratPool.Clear();
        }

        /// <summary>Sends the chance from F12 to the server (at the start of the game and whenever it changes; the server rolls it at a raid start).</summary>
        public static void SendChance()
        {
            int chance = Settings.PackratChance?.Value ?? 0;
            System.Threading.Tasks.Task.Run(() =>
            {
                try
                {
                    SPT.Common.Http.RequestHandler.GetJson("/liveraid/packrat/chance/" + chance.ToString(CultureInfo.InvariantCulture));
                }
                catch (System.Exception)
                {
                    // the server part is off or not reached - no packrat then
                }
            });
        }

        /// <summary>
        /// Is this bot the raid's packrat? Only a PMC without a long gun can be, so the server is asked only for those (at most every 5 s until it
        /// has a name for this raid).
        /// </summary>
        public static bool Check(BotOwner bot, BotKind kind)
        {
            if (kind != BotKind.Pmc || (Settings.PackratChance?.Value ?? 0) <= 0 || bot?.GetPlayer?.Equipment == null)
            {
                return false;
            }

            Inventory inv = bot.GetPlayer.Inventory;
            if (inv?.Equipment?.GetSlot(EquipmentSlot.FirstPrimaryWeapon)?.ContainedItem != null
                || inv?.Equipment?.GetSlot(EquipmentSlot.SecondPrimaryWeapon)?.ContainedItem != null)
            {
                return false;
            }

            // A lone group was given the packrat's profile (Patches/PackratPoolPatch.cs): that is the one
            if (_assigned != null)
            {
                return _assigned == bot.ProfileId;
            }

            if (_chosen != null)
            {
                return _chosen == bot.ProfileId;
            }

            if (!_tagged.Contains(bot.ProfileId))
            {
                Refresh();
            }

            // Without the pool patch: the first of the server's candidates to come in is the packrat of this raid (the others are just poor PMCs with a big bag)
            if (_tagged.Contains(bot.ProfileId) && !Patches.PackratPool.Active)
            {
                _chosen = bot.ProfileId;
                return true;
            }

            return false;
        }

        public static void Shape(BotProfile p, BotOwner bot)
        {
            p.Packrat = true;
            p.Style = PlayStyle.Looter;
            p.Aggression = 0.05f;
            p.LootGreed = 2.4f;
            p.Explore = 1.8f;
            p.Camp = 0.2f;
            p.QuestFocus = 0.2f;
            p.Snipe = 0.2f;
            p.HotDrop = false;
            p.SainPersonality = EPersonality.Normal;
            string bag = bot.GetPlayer?.Inventory?.Equipment?.GetSlot(EquipmentSlot.Backpack)?.ContainedItem?.ShortName?.Localized() ?? "no bag";
            string gun = bot.GetPlayer?.Inventory?.Equipment?.GetSlot(EquipmentSlot.Holster)?.ContainedItem?.ShortName?.Localized() ?? "no pistol";
            Seen = $"{p.Name} ({gun}, {bag})";
            Log.Info($"LR Packrat: {p.Name} is this raid's packrat - {gun}, {bag}; it loots and keeps out of fights");
        }

        /// <summary>The packrat comes alone: once active, it leaves the group it was generated in (QuestingBots separates it, the others go on without it).</summary>
        public static void Tick()
        {
            if (_toSeparate.Count == 0)
            {
                return;
            }

            foreach (BotOwner b in _toSeparate.ToArray())
            {
                if (b == null || b.IsDead)
                {
                    _toSeparate.Remove(b);
                    continue;
                }

                if (b.BotState != EBotState.Active)
                {
                    continue;
                }

                _toSeparate.Remove(b);
                try
                {
                    int members = b.BotsGroup?.MembersCount ?? 1;
                    if (members > 1)
                    {
                        QuestingBots.BotLogic.HiveMind.BotHiveMindMonitor.SeparateBotFromGroup(b);
                        Log.Info($"LR Packrat: {b.Profile.Nickname} leaves its group of {members} - it goes alone");
                    }
                }
                catch (System.Exception e)
                {
                    Diag.Report("Packrat.Separate", e);
                }
            }
        }

        private static string Field(string json, string key)
        {
            if (string.IsNullOrEmpty(json))
            {
                return null;
            }

            string tag = "\"" + key + "\":\"";
            int i = json.IndexOf(tag, System.StringComparison.Ordinal);
            if (i < 0)
            {
                return null;
            }

            i += tag.Length;
            int j = json.IndexOf('"', i);
            return j > i ? json.Substring(i, j - i) : null;
        }
    }
}
